SELECT p.id AS id, ((GREATEST((CASE WHEN public.immutable_unaccent(lower(p.name)) = $5::text THEN 120 WHEN public.immutable_unaccent(lower(p.name)) LIKE $6::text ESCAPE '\' OR public.immutable_unaccent(lower(p.name)) LIKE $7::text ESCAPE '\' OR public.immutable_unaccent(lower(p.name)) LIKE $8::text ESCAPE '\' THEN 40 WHEN public.immutable_unaccent(lower(p.name)) LIKE $9::text ESCAPE '\' OR public.immutable_unaccent(lower(p.name)) LIKE $10::text ESCAPE '\' THEN 25 WHEN public.immutable_unaccent(lower(p.name)) LIKE $4::text ESCAPE '\' THEN 12 ELSE 0 END), (CASE WHEN public.immutable_unaccent(lower(p.sku)) = $5::text THEN 110 WHEN public.immutable_unaccent(lower(p.sku)) LIKE $6::text ESCAPE '\' OR public.immutable_unaccent(lower(p.sku)) LIKE $7::text ESCAPE '\' OR public.immutable_unaccent(lower(p.sku)) LIKE $8::text ESCAPE '\' THEN 30 WHEN public.immutable_unaccent(lower(p.sku)) LIKE $9::text ESCAPE '\' OR public.immutable_unaccent(lower(p.sku)) LIKE $10::text ESCAPE '\' THEN 20 WHEN public.immutable_unaccent(lower(p.sku)) LIKE $4::text ESCAPE '\' THEN 10 ELSE 0 END), (CASE WHEN public.immutable_unaccent(lower(p.barcode)) = $5::text THEN 110 WHEN public.immutable_unaccent(lower(p.barcode)) LIKE $6::text ESCAPE '\' OR public.immutable_unaccent(lower(p.barcode)) LIKE $7::text ESCAPE '\' OR public.immutable_unaccent(lower(p.barcode)) LIKE $8::text ESCAPE '\' THEN 25 WHEN public.immutable_unaccent(lower(p.barcode)) LIKE $9::text ESCAPE '\' OR public.immutable_unaccent(lower(p.barcode)) LIKE $10::text ESCAPE '\' THEN 15 WHEN public.immutable_unaccent(lower(p.barcode)) LIKE $4::text ESCAPE '\' THEN 8 ELSE 0 END), (CASE WHEN public.immutable_unaccent(lower(p.description)) = $5::text THEN 100 WHEN public.immutable_unaccent(lower(p.description)) LIKE $6::text ESCAPE '\' OR public.immutable_unaccent(lower(p.description)) LIKE $7::text ESCAPE '\' OR public.immutable_unaccent(lower(p.description)) LIKE $8::text ESCAPE '\' THEN 15 WHEN public.immutable_unaccent(lower(p.description)) LIKE $9::text ESCAPE '\' OR public.immutable_unaccent(lower(p.description)) LIKE $10::text ESCAPE '\' THEN 10 WHEN public.immutable_unaccent(lower(p.description)) LIKE $4::text ESCAPE '\' THEN 5 ELSE 0 END), (SELECT COALESCE(MAX(GREATEST((CASE WHEN public.immutable_unaccent(lower(v2.name)) = $5::text THEN 105 WHEN public.immutable_unaccent(lower(v2.name)) LIKE $6::text ESCAPE '\' OR public.immutable_unaccent(lower(v2.name)) LIKE $7::text ESCAPE '\' OR public.immutable_unaccent(lower(v2.name)) LIKE $8::text ESCAPE '\' THEN 30 WHEN public.immutable_unaccent(lower(v2.name)) LIKE $9::text ESCAPE '\' OR public.immutable_unaccent(lower(v2.name)) LIKE $10::text ESCAPE '\' THEN 18 WHEN public.immutable_unaccent(lower(v2.name)) LIKE $4::text ESCAPE '\' THEN 8 ELSE 0 END), (CASE WHEN public.immutable_unaccent(lower(v2.sku)) = $5::text THEN 110 WHEN public.immutable_unaccent(lower(v2.sku)) LIKE $6::text ESCAPE '\' OR public.immutable_unaccent(lower(v2.sku)) LIKE $7::text ESCAPE '\' OR public.immutable_unaccent(lower(v2.sku)) LIKE $8::text ESCAPE '\' THEN 30 WHEN public.immutable_unaccent(lower(v2.sku)) LIKE $9::text ESCAPE '\' OR public.immutable_unaccent(lower(v2.sku)) LIKE $10::text ESCAPE '\' THEN 20 WHEN public.immutable_unaccent(lower(v2.sku)) LIKE $4::text ESCAPE '\' THEN 10 ELSE 0 END))), 0) FROM public.product_variants v2 WHERE v2.product_id = p.id))) + 15 + (CASE WHEN ((CASE WHEN public.immutable_unaccent(lower(p.name)) = $5::text THEN 120 WHEN public.immutable_unaccent(lower(p.name)) LIKE $6::text ESCAPE '\' OR public.immutable_unaccent(lower(p.name)) LIKE $7::text ESCAPE '\' OR public.immutable_unaccent(lower(p.name)) LIKE $8::text ESCAPE '\' THEN 40 WHEN public.immutable_unaccent(lower(p.name)) LIKE $9::text ESCAPE '\' OR public.immutable_unaccent(lower(p.name)) LIKE $10::text ESCAPE '\' THEN 25 WHEN public.immutable_unaccent(lower(p.name)) LIKE $4::text ESCAPE '\' THEN 12 ELSE 0 END) > 0) THEN 25 ELSE 0 END) + (CASE WHEN btrim(regexp_replace(public.immutable_unaccent(lower(p.sku)), '[^[:alnum:] ]+', ' ', 'g')) = $11::text OR EXISTS (SELECT 1 FROM public.product_variants v3 WHERE v3.product_id = p.id AND btrim(regexp_replace(public.immutable_unaccent(lower(v3.sku)), '[^[:alnum:] ]+', ' ', 'g')) = $11::text) THEN 20 ELSE 0 END) + (CASE WHEN btrim(regexp_replace(public.immutable_unaccent(lower(p.barcode)), '[^[:alnum:] ]+', ' ', 'g')) = $11::text OR EXISTS (SELECT 1 FROM public.product_variants v4 WHERE v4.product_id = p.id AND btrim(regexp_replace(public.immutable_unaccent(lower(v4.barcode)), '[^[:alnum:] ]+', ' ', 'g')) = $11::text) THEN 30 ELSE 0 END)) AS score, 1 AS coverage FROM public.products p WHERE p.store_id = $1::int AND p.state = $2::product_state_enum AND p.is_sellable = $3::boolean AND (public.immutable_unaccent(lower(p.name)) LIKE $4::text ESCAPE '\' OR public.immutable_unaccent(lower(p.sku)) LIKE $4::text ESCAPE '\' OR public.immutable_unaccent(lower(p.description)) LIKE $4::text ESCAPE '\' OR EXISTS (SELECT 1 FROM public.product_variants v WHERE v.product_id = p.id AND (public.immutable_unaccent(lower(v.name)) LIKE $4::text ESCAPE '\' OR public.immutable_unaccent(lower(v.sku)) LIKE $4::text ESCAPE '\'))) ORDER BY score DESC, coverage DESC, p.is_featured DESC, p.created_at DESC NULLS LAST, p.id DESC LIMIT $12::int OFFSET $13::int
